import Foundation

/// Живой текст ответа, который сейчас стримится. Существует только в памяти
/// (исключение из offline-first): ViewModel накладывает его поверх сообщения
/// со статусом `streaming`, пока в базе лежит более старая версия текста.
struct StreamingDraft: Hashable, Sendable {
    let messageId: UUID
    let text: String
}

/// То, что экранам нужно от `ChatService` (шаг 3.2) сверх чтения из `ChatRepository`.
/// `ChatService` реализует этот протокол; превью и `-mockData` — `PreviewChatSession`.
///
/// Объявлен в `Features`, а не в `Domain`: это контракт UI-слоя, а `ChatService`
/// будет писаться параллельно (см. отчёт по шагам 4.1–4.4).
@MainActor
protocol ChatSession: AnyObject {
    /// Черновик стримящегося ответа в чате: текущее значение сразу, дальше — при каждом токене.
    /// `nil` — в этом чате сейчас ничего не стримится.
    func draftUpdates(chatId: UUID) -> AsyncStream<StreamingDraft?>

    /// Удаляет чат и отменяет его генерацию, если она идёт.
    func deleteChat(id: UUID) async throws
}

/// Всё, из чего собираются экраны. Создаётся в `AppContainer`.
@MainActor
struct ChatDependencies {
    let repository: any ChatRepository
    let session: any ChatSession
    /// Подпись под названием чата («Groq · <model>»).
    let modelName: LocalizedStringResource
}

#if DEBUG
import Foundation

/// `ChatSession` для превью и `-mockData` поверх фейков из `Mocks/`.
/// Ответ в статусе `streaming` «догенерирует» `FakeLLMProvider`: черновик растёт
/// по токенам, в конце текст пишется в репозиторий со статусом `done`.
@MainActor
final class PreviewChatSession: ChatSession {
    private let repository: any ChatRepository
    private let provider: FakeLLMProvider

    init(
        repository: any ChatRepository,
        provider: FakeLLMProvider = FakeLLMProvider(script: .reply(PreviewChatSession.continuation,
                                                                    tokenDelay: .milliseconds(120)))
    ) {
        self.repository = repository
        self.provider = provider
    }

    func draftUpdates(chatId: UUID) -> AsyncStream<StreamingDraft?> {
        let repository = repository
        let provider = provider
        return AsyncStream { continuation in
            let task = Task {
                var messages = repository.observeMessages(chatId: chatId).makeAsyncIterator()
                guard let streaming = await messages.next()?.first(where: { $0.status == .streaming }) else {
                    continuation.yield(nil)
                    continuation.finish()
                    return
                }
                var text = streaming.text
                continuation.yield(StreamingDraft(messageId: streaming.id, text: text))
                do {
                    for try await token in provider.streamReply(to: []) {
                        text += token
                        continuation.yield(StreamingDraft(messageId: streaming.id, text: text))
                    }
                    if !Task.isCancelled {
                        try await repository.updateMessage(id: streaming.id, text: text, status: .done, failure: nil)
                    }
                } catch {
                    // Превью: ошибки фейка не показываем, черновик просто исчезает.
                }
                continuation.yield(nil)
                continuation.finish()
            }
            continuation.onTermination = { _ in task.cancel() }
        }
    }

    func deleteChat(id: UUID) async throws {
        try await repository.deleteChat(id: id)
    }

    /// Продолжение ответа из `PreviewData` (содержимое переписки, не строка интерфейса).
    nonisolated static let continuation = """
         data races are caught at compile time instead of at runtime. \
        A lock only protects the code that remembers to take it; an actor protects *every* access.
        """
}

extension ChatDependencies {
    static func preview(repository: any ChatRepository = PreviewData.repository()) -> ChatDependencies {
        ChatDependencies(
            repository: repository,
            session: PreviewChatSession(repository: repository),
            modelName: "Groq · gpt-oss-120b"
        )
    }
}
#endif

import Foundation
import Observation

/// Группа «Recents» по дате последнего сообщения.
enum ChatDateGroup: CaseIterable, Hashable, Sendable {
    case today
    case yesterday
    case previous7Days
    case older

    var title: LocalizedStringResource {
        switch self {
        case .today: "Today"
        case .yesterday: "Yesterday"
        case .previous7Days: "Previous 7 days"
        case .older: "Older"
        }
    }

    static func group(for date: Date, now: Date, calendar: Calendar) -> ChatDateGroup {
        let today = calendar.startOfDay(for: now)
        let day = calendar.startOfDay(for: date)
        let days = calendar.dateComponents([.day], from: day, to: today).day ?? 0
        switch days {
        case ...0: return .today
        case 1: return .yesterday
        case 2...7: return .previous7Days
        default: return .older
        }
    }
}

struct ChatSection: Identifiable, Hashable, Sendable {
    let group: ChatDateGroup
    let chats: [Chat]

    var id: ChatDateGroup { group }
}

/// Сайдбар: список чатов из репозитория, поиск, выбор, переименование и удаление.
/// Выбранный чат (`nil` — «New chat», черновик) хранится здесь же: его читают
/// и сайдбар, и верхняя панель чата.
@MainActor
@Observable
final class ChatListViewModel {
    private(set) var chats: [Chat] = []
    /// Пока не пришло первое значение из базы, пустое состояние не показываем.
    private(set) var hasLoaded = false
    var searchText = ""
    var selectedChatId: UUID?

    /// Чат, который сейчас переименовывают (алерт с полем ввода).
    private(set) var renamingChat: Chat?
    var renameText = ""
    /// Чат, удаление которого ждёт подтверждения.
    var chatPendingDeletion: Chat?
    private(set) var actionFailed = false

    @ObservationIgnored private let repository: any ChatRepository
    @ObservationIgnored private let session: any ChatSession
    @ObservationIgnored private let now: () -> Date
    @ObservationIgnored private let calendar: Calendar

    init(
        repository: any ChatRepository,
        session: any ChatSession,
        now: @escaping () -> Date = Date.init,
        calendar: Calendar = .current
    ) {
        self.repository = repository
        self.session = session
        self.now = now
        self.calendar = calendar
    }

    var selectedChat: Chat? {
        selectedChatId.flatMap { id in chats.first { $0.id == id } }
    }

    /// Чаты, подходящие под поиск, сгруппированные по дате; пустые группы опущены.
    var sections: [ChatSection] {
        let query = searchText.trimmingCharacters(in: .whitespacesAndNewlines)
        let visible = query.isEmpty ? chats : chats.filter { $0.title.localizedStandardContains(query) }
        let date = now()
        let grouped = Dictionary(grouping: visible) {
            ChatDateGroup.group(for: $0.updatedAt, now: date, calendar: calendar)
        }
        return ChatDateGroup.allCases.compactMap { group in
            grouped[group].map { ChatSection(group: group, chats: $0) }
        }
    }

    var isEmpty: Bool { hasLoaded && chats.isEmpty }
    var hasNoSearchResults: Bool { !chats.isEmpty && sections.isEmpty }

    /// Подписка на базу; живёт, пока жива задача вызывающего (`.task` во View).
    func observe() async {
        for await chats in repository.observeChats() {
            self.chats = chats
            hasLoaded = true
            if let selectedChatId, !chats.contains(where: { $0.id == selectedChatId }) {
                self.selectedChatId = nil
            }
        }
    }

    func startNewChat() {
        selectedChatId = nil
        searchText = ""
    }

    func select(_ chat: Chat) {
        selectedChatId = chat.id
    }

    // MARK: Переименование

    func beginRename(_ chat: Chat) {
        renamingChat = chat
        renameText = chat.title
    }

    func cancelRename() {
        renamingChat = nil
    }

    var canCommitRename: Bool {
        !renameText.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty
    }

    func commitRename() async {
        guard let chat = renamingChat else { return }
        renamingChat = nil
        let title = renameText.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !title.isEmpty, title != chat.title else { return }
        do {
            try await repository.renameChat(id: chat.id, title: title)
        } catch {
            actionFailed = true
        }
    }

    // MARK: Удаление

    func requestDelete(_ chat: Chat) {
        chatPendingDeletion = chat
    }

    func confirmDelete() async {
        guard let chat = chatPendingDeletion else { return }
        chatPendingDeletion = nil
        if selectedChatId == chat.id { selectedChatId = nil }
        do {
            try await session.deleteChat(id: chat.id)
        } catch {
            actionFailed = true
        }
    }

    func dismissActionFailure() {
        actionFailed = false
    }
}

import SwiftUI

/// Сайдбар: «New chat», поиск, «Recents» по датам. Одна и та же вью — и в
/// выезжающей панели на iPhone, и в колонке `NavigationSplitView` на iPad.
/// Алерты переименования/удаления вешает `RootView`: они общие с верхней панелью.
struct SidebarView: View {
    @Bindable var viewModel: ChatListViewModel
    /// Вызывается после выбора чата или «New chat» — iPhone закрывает панель.
    var onNavigate: () -> Void = {}

    var body: some View {
        VStack(spacing: 0) {
            header
            content
        }
        .background(.appBackground)
    }

    private var header: some View {
        VStack(spacing: 12) {
            SearchField(text: $viewModel.searchText)

            Button {
                viewModel.startNewChat()
                onNavigate()
            } label: {
                Label("New chat", systemImage: "square.and.pencil")
                    .font(.body.weight(.medium))
                    .frame(maxWidth: .infinity, alignment: .leading)
                    .padding(.vertical, 10)
                    .padding(.horizontal, 12)
                    .contentShape(.rect)
            }
            .buttonStyle(.plain)
            .foregroundStyle(.appAccent)
        }
        .padding(.horizontal, 12)
        .padding(.top, 12)
    }

    @ViewBuilder
    private var content: some View {
        if viewModel.isEmpty {
            ContentUnavailableView {
                Label("No chats yet", systemImage: "bubble.left.and.bubble.right")
            } description: {
                Text("Your conversations will appear here.")
            }
        } else if viewModel.hasNoSearchResults {
            ContentUnavailableView.search(text: viewModel.searchText)
        } else {
            chatList
        }
    }

    private var chatList: some View {
        List {
            Text("Recents")
                .font(.subheadline.weight(.semibold))
                .foregroundStyle(.secondary)
                .listRowBackground(Color.clear)
                .listRowSeparator(.hidden)
            ForEach(viewModel.sections) { section in
                Section {
                    ForEach(section.chats) { chat in
                        row(for: chat)
                    }
                } header: {
                    Text(section.group.title)
                        .font(.footnote)
                        .foregroundStyle(.secondary)
                }
            }
        }
        .listStyle(.plain)
        .scrollContentBackground(.hidden)
        .scrollDismissesKeyboard(.immediately)
    }

    private func row(for chat: Chat) -> some View {
        let isSelected = chat.id == viewModel.selectedChatId
        return Button {
            viewModel.select(chat)
            onNavigate()
        } label: {
            // Название чата — пользовательские данные, а не строка интерфейса.
            Text(chat.title)
                .lineLimit(1)
                .frame(maxWidth: .infinity, alignment: .leading)
                .contentShape(.rect)
        }
        .buttonStyle(.plain)
        .listRowSeparator(.hidden)
        .listRowBackground(
            RoundedRectangle(cornerRadius: 10)
                .fill(isSelected ? AnyShapeStyle(.appSurface) : AnyShapeStyle(.clear))
                .padding(.horizontal, 8)
        )
        .accessibilityAddTraits(isSelected ? .isSelected : [])
        .contextMenu {
            Button("Rename", systemImage: "pencil") { viewModel.beginRename(chat) }
            Button("Delete", systemImage: "trash", role: .destructive) { viewModel.requestDelete(chat) }
        }
    }
}

private struct SearchField: View {
    @Binding var text: String

    var body: some View {
        HStack(spacing: 8) {
            Image(systemName: "magnifyingglass")
                .foregroundStyle(.secondary)
            TextField("Search", text: $text)
                .textInputAutocapitalization(.never)
                .autocorrectionDisabled()
                .submitLabel(.search)
            if !text.isEmpty {
                Button("Clear search", systemImage: "xmark.circle.fill") { text = "" }
                    .labelStyle(.iconOnly)
                    .foregroundStyle(.secondary)
                    .buttonStyle(.plain)
            }
        }
        .padding(.horizontal, 12)
        .padding(.vertical, 9)
        .background(.appSurface, in: .rect(cornerRadius: 12))
    }
}

/// Алерты переименования, подтверждения удаления и ошибки действия — общие для
/// сайдбара и верхней панели чата.
struct ChatListAlerts: ViewModifier {
    @Bindable var viewModel: ChatListViewModel

    func body(content: Content) -> some View {
        content
            .alert("Rename chat", isPresented: renameBinding) {
                TextField("Title", text: $viewModel.renameText)
                Button("Cancel", role: .cancel) { viewModel.cancelRename() }
                Button("Save") { Task { await viewModel.commitRename() } }
                    .disabled(!viewModel.canCommitRename)
            }
            .confirmationDialog(
                "Delete this chat?",
                isPresented: deleteBinding,
                titleVisibility: .visible
            ) {
                Button("Delete", role: .destructive) { Task { await viewModel.confirmDelete() } }
                Button("Cancel", role: .cancel) { viewModel.chatPendingDeletion = nil }
            } message: {
                Text("The chat and all its messages will be removed.")
            }
            .alert("Something went wrong", isPresented: failureBinding) {
                Button("OK", role: .cancel) { viewModel.dismissActionFailure() }
            } message: {
                Text("Please try again.")
            }
    }

    private var renameBinding: Binding<Bool> {
        Binding { viewModel.renamingChat != nil } set: { if !$0 { viewModel.cancelRename() } }
    }

    private var deleteBinding: Binding<Bool> {
        Binding { viewModel.chatPendingDeletion != nil } set: { if !$0 { viewModel.chatPendingDeletion = nil } }
    }

    private var failureBinding: Binding<Bool> {
        Binding { viewModel.actionFailed } set: { if !$0 { viewModel.dismissActionFailure() } }
    }
}

extension View {
    func chatListAlerts(_ viewModel: ChatListViewModel) -> some View {
        modifier(ChatListAlerts(viewModel: viewModel))
    }
}

#if DEBUG
private struct SidebarPreview: View {
    @State private var viewModel: ChatListViewModel

    init(dependencies: ChatDependencies) {
        _viewModel = State(initialValue: ChatListViewModel(repository: dependencies.repository,
                                                           session: dependencies.session))
    }

    var body: some View {
        SidebarView(viewModel: viewModel)
            .chatListAlerts(viewModel)
            .task { await viewModel.observe() }
    }
}

#Preview("Light") { SidebarPreview(dependencies: .preview()) }
#Preview("Dark") { SidebarPreview(dependencies: .preview()).preferredColorScheme(.dark) }
#Preview("Empty") { SidebarPreview(dependencies: .preview(repository: InMemoryChatRepository())) }
#endif

import Foundation
import Testing
@testable import AIChat

@MainActor
struct ChatListViewModelTests {
    private static let calendar: Calendar = {
        var calendar = Calendar(identifier: .gregorian)
        calendar.timeZone = TimeZone(identifier: "UTC")!
        return calendar
    }()

    /// Среда, 12:00 UTC.
    private static let now = Date(timeIntervalSince1970: 1_791_288_000)

    private static func chat(_ title: String, daysAgo: Double) -> Chat {
        let date = now.addingTimeInterval(-daysAgo * 86_400)
        return Chat(id: UUID(), title: title, createdAt: date, updatedAt: date)
    }

    private static func message(in chat: Chat) -> Message {
        Message(chatId: chat.id, role: .user, text: "Hi", status: .sent, createdAt: chat.updatedAt)
    }

    private func makeViewModel(chats: [Chat]) async throws -> (ChatListViewModel, InMemoryChatRepository, Task<Void, Never>) {
        let repository = InMemoryChatRepository(chats: chats, messages: chats.map(Self.message(in:)))
        let viewModel = ChatListViewModel(
            repository: repository,
            session: PreviewChatSession(repository: repository),
            now: { Self.now },
            calendar: Self.calendar
        )
        let observation = Task { await viewModel.observe() }
        try await waitUntil { viewModel.hasLoaded }
        return (viewModel, repository, observation)
    }

    @Test(arguments: [
        (0.0, ChatDateGroup.today),
        (0.4, .today),
        (1.0, .yesterday),
        (2.0, .previous7Days),
        (7.0, .previous7Days),
        (8.0, .older),
        (400.0, .older),
    ])
    func groupsByCalendarDay(daysAgo: Double, expected: ChatDateGroup) {
        let date = Self.now.addingTimeInterval(-daysAgo * 86_400)
        #expect(ChatDateGroup.group(for: date, now: Self.now, calendar: Self.calendar) == expected)
    }

    @Test func sectionsSkipEmptyGroupsAndKeepOrder() async throws {
        let (viewModel, _, observation) = try await makeViewModel(chats: [
            Self.chat("Old", daysAgo: 30), Self.chat("Fresh", daysAgo: 0), Self.chat("Last week", daysAgo: 3),
        ])
        defer { observation.cancel() }

        #expect(viewModel.sections.map(\.group) == [.today, .previous7Days, .older])
        #expect(viewModel.sections.map { $0.chats.map(\.title) } == [["Fresh"], ["Last week"], ["Old"]])
    }

    @Test func searchFiltersByTitleIgnoringCase() async throws {
        let (viewModel, _, observation) = try await makeViewModel(chats: [
            Self.chat("Swift actors", daysAgo: 0), Self.chat("Trip ideas", daysAgo: 1),
        ])
        defer { observation.cancel() }

        viewModel.searchText = "  SWIFT "
        #expect(viewModel.sections.flatMap(\.chats).map(\.title) == ["Swift actors"])

        viewModel.searchText = "nothing"
        #expect(viewModel.hasNoSearchResults)
        #expect(!viewModel.isEmpty)
    }

    @Test func emptyStateOnlyAfterFirstLoad() async throws {
        let repository = InMemoryChatRepository()
        let viewModel = ChatListViewModel(repository: repository, session: PreviewChatSession(repository: repository))
        #expect(!viewModel.isEmpty)

        let observation = Task { await viewModel.observe() }
        defer { observation.cancel() }
        try await waitUntil { viewModel.hasLoaded }
        #expect(viewModel.isEmpty)
    }

    @Test func renameTrimsTitleAndIgnoresBlank() async throws {
        let chat = Self.chat("Old title", daysAgo: 0)
        let (viewModel, _, observation) = try await makeViewModel(chats: [chat])
        defer { observation.cancel() }

        viewModel.beginRename(chat)
        viewModel.renameText = "   "
        #expect(!viewModel.canCommitRename)
        await viewModel.commitRename()
        #expect(viewModel.renamingChat == nil)
        #expect(viewModel.chats.first?.title == "Old title")

        viewModel.beginRename(chat)
        viewModel.renameText = "  New title \n"
        await viewModel.commitRename()
        try await waitUntil { viewModel.chats.first?.title == "New title" }
    }

    @Test func deleteSelectedChatFallsBackToNewChat() async throws {
        let first = Self.chat("First", daysAgo: 0)
        let second = Self.chat("Second", daysAgo: 1)
        let (viewModel, _, observation) = try await makeViewModel(chats: [first, second])
        defer { observation.cancel() }

        viewModel.select(first)
        viewModel.requestDelete(first)
        await viewModel.confirmDelete()

        #expect(viewModel.selectedChatId == nil)
        try await waitUntil { viewModel.chats.map(\.id) == [second.id] }
        #expect(!viewModel.actionFailed)
    }

    @Test func selectionResetsWhenChatDisappears() async throws {
        let chat = Self.chat("Doomed", daysAgo: 0)
        let (viewModel, repository, observation) = try await makeViewModel(chats: [chat])
        defer { observation.cancel() }

        viewModel.select(chat)
        try await repository.deleteChat(id: chat.id)

        try await waitUntil { viewModel.selectedChatId == nil }
    }
}

