import Foundation

extension AppContainer {
    /// Зависимости экранов. Реальных репозитория и `ChatService` ещё нет (шаги 1.3, 3.2),
    /// поэтому пока экраны собираются только с `-mockData` (фейки из `Mocks/`);
    /// без аргумента остаётся заглушка — фейки в обычный запуск не попадают.
    func makeChatDependencies() -> ChatDependencies? {
        #if DEBUG
        if launchOptions.useMockData { return .preview() }
        #endif
        return nil
    }
}

import SwiftUI

@main
struct AIChatApp: App {
    @State private var container: AppContainer
    @State private var screens: ChatDependencies?

    init() {
        let container = AppContainer(
            environment: AppContainer.environment(for: .processInfo),
            launchOptions: LaunchOptions(arguments: ProcessInfo.processInfo.arguments)
        )
        _container = State(initialValue: container)
        _screens = State(initialValue: container.environment == .live ? container.makeChatDependencies() : nil)
    }

    var body: some Scene {
        WindowGroup {
            switch container.environment {
            case .live:
                if let screens {
                    RootView(dependencies: screens)
                } else {
                    PlaceholderView()
                }
            case .unitTests:
                EmptyView()
            }
        }
    }
}

private struct PlaceholderView: View {
    var body: some View {
        Text("AI Chat")
            .font(.largeTitle)
            .foregroundStyle(.primary)
            .frame(maxWidth: .infinity, maxHeight: .infinity)
            .background(Color("Background"))
    }
}

import Foundation
import Observation

/// Лента сообщений одного чата. Сообщения — только из базы (`observeMessages`);
/// поверх ответа в статусе `streaming` накладывается живой черновик из `ChatSession`.
@MainActor
@Observable
final class ChatViewModel {
    /// `nil` — новый чат: в базе его ещё нет, лента пустая.
    let chatId: UUID?
    private(set) var messages: [Message] = []
    private(set) var draft: StreamingDraft?
    /// Пока не пришло первое значение из базы, пустое состояние не показываем.
    private(set) var hasLoaded: Bool
    /// Пользователь у нижнего края ленты: новые токены прокручивают её вниз.
    /// Меняется только от действий пользователя, а не от роста контента.
    private(set) var isPinnedToBottom = true

    @ObservationIgnored private let repository: any ChatRepository
    @ObservationIgnored private let session: any ChatSession

    init(chatId: UUID?, repository: any ChatRepository, session: any ChatSession) {
        self.chatId = chatId
        self.repository = repository
        self.session = session
        hasLoaded = chatId == nil
    }

    /// Сообщения для показа: у стримящегося ответа текст — из черновика.
    var displayedMessages: [Message] {
        guard let draft else { return messages }
        return messages.map { message in
            guard message.id == draft.messageId, message.status == .streaming else { return message }
            var message = message
            message.text = draft.text
            return message
        }
    }

    var showsScrollToBottomButton: Bool { !isPinnedToBottom && !messages.isEmpty }

    // MARK: Подписки (живут, пока жива задача вызывающего — `.task` во View)

    func observeMessages() async {
        guard let chatId else { return }
        for await messages in repository.observeMessages(chatId: chatId) {
            self.messages = messages
            hasLoaded = true
        }
    }

    func observeDraft() async {
        guard let chatId else { return }
        for await draft in session.draftUpdates(chatId: chatId) {
            self.draft = draft
        }
    }

    // MARK: Прокрутка

    /// Пользователь прокрутил ленту: у нижнего края — снова следим за новыми токенами.
    func userScrolled(isAtBottom: Bool) {
        isPinnedToBottom = isAtBottom
    }

    func scrollToBottomTapped() {
        isPinnedToBottom = true
    }
}

import SwiftUI

/// Лента сообщений. Автоскролл — только если пользователь внизу; иначе
/// показывается кнопка «вниз».
struct ChatView: View {
    let viewModel: ChatViewModel

    @State private var position = ScrollPosition(edge: .bottom)
    /// Последнее известное «у нижнего края» — применяется, когда пользователь отпустил ленту.
    @State private var isNearBottom = true
    @State private var isUserScrolling = false

    /// Насколько можно не доскроллить до конца и всё ещё считаться «внизу».
    private let bottomTolerance: CGFloat = 48

    var body: some View {
        ScrollView {
            LazyVStack(alignment: .leading, spacing: 20) {
                ForEach(viewModel.displayedMessages) { message in
                    MessageRow(message: message)
                }
            }
            .padding(.horizontal, 16)
            .padding(.vertical, 12)
        }
        .scrollPosition($position)
        .defaultScrollAnchor(.bottom)
        .scrollDismissesKeyboard(.interactively)
        .onScrollGeometryChange(for: Bool.self) { geometry in
            geometry.visibleRect.maxY >= geometry.contentSize.height + geometry.contentInsets.bottom - bottomTolerance
        } action: { _, isNearBottom in
            self.isNearBottom = isNearBottom
            if isUserScrolling { viewModel.userScrolled(isAtBottom: isNearBottom) }
        }
        .onScrollPhaseChange { _, phase in
            // Программная прокрутка (`.animating`) и рост контента не снимают «прилипание» к низу.
            isUserScrolling = phase == .interacting || phase == .tracking || phase == .decelerating
            if phase == .idle || isUserScrolling { viewModel.userScrolled(isAtBottom: isNearBottom) }
        }
        .onScrollGeometryChange(for: CGFloat.self) { $0.contentSize.height } action: { old, new in
            if new > old, viewModel.isPinnedToBottom, !isUserScrolling {
                position.scrollTo(edge: .bottom)
            }
        }
        .overlay(alignment: .bottom) {
            if viewModel.showsScrollToBottomButton {
                ScrollToBottomButton {
                    viewModel.scrollToBottomTapped()
                    withAnimation(.snappy) { position.scrollTo(edge: .bottom) }
                }
                .padding(.bottom, 12)
                .transition(.scale(scale: 0.6).combined(with: .opacity))
            }
        }
        .animation(.snappy, value: viewModel.showsScrollToBottomButton)
        .background(.appBackground)
        .task { await viewModel.observeMessages() }
        .task { await viewModel.observeDraft() }
    }
}

private struct ScrollToBottomButton: View {
    let action: () -> Void

    var body: some View {
        Button("Scroll to bottom", systemImage: "arrow.down", action: action)
            .labelStyle(.iconOnly)
            .font(.body.weight(.semibold))
            .foregroundStyle(.primary)
            .frame(width: 40, height: 40)
            .background(.appSurface, in: .circle)
            .overlay { Circle().strokeBorder(.secondary.opacity(0.25)) }
            .shadow(color: .primary.opacity(0.08), radius: 6, y: 2)
            .contentShape(.circle)
    }
}

/// Одно сообщение: пузырь пользователя справа или ответ ассистента на всю ширину.
struct MessageRow: View {
    let message: Message

    var body: some View {
        switch message.role {
        case .user: UserBubble(text: message.text)
        case .assistant: AssistantText(text: message.text)
        }
    }
}

private struct UserBubble: View {
    let text: String

    var body: some View {
        // Текст сообщения — пользовательские данные, а не строка интерфейса.
        Text(text)
            .textStyle(.userMessage)
            .foregroundStyle(.primary)
            .textSelection(.enabled)
            .padding(.horizontal, 14)
            .padding(.vertical, 10)
            .background(.appSurface, in: .rect(cornerRadius: 20))
            .containerRelativeFrame(.horizontal, alignment: .trailing) { width, _ in width * 0.8 }
            .frame(maxWidth: .infinity, alignment: .trailing)
    }
}

private struct AssistantText: View {
    let text: String

    var body: some View {
        // Блочный markdown — шаг 4.7; пока только инлайн-разметка.
        Text(Self.inlineMarkdown(text))
            .textStyle(.assistantMessage)
            .foregroundStyle(.primary)
            .lineSpacing(3)
            .textSelection(.enabled)
            .frame(maxWidth: .infinity, alignment: .leading)
            // Плавное появление новых токенов.
            .contentTransition(.opacity)
            .animation(.easeOut(duration: 0.25), value: text)
    }

    private static func inlineMarkdown(_ text: String) -> AttributedString {
        let options = AttributedString.MarkdownParsingOptions(interpretedSyntax: .inlineOnlyPreservingWhitespace)
        return (try? AttributedString(markdown: text, options: options)) ?? AttributedString(text)
    }
}

