    init(monitor: any ConnectivityMonitoring) {
        self.monitor = monitor
        isOnline = monitor.isOnline
    }

    /// Подписка живёт, пока жива задача вызывающего (`.task` во View).
    func observe() async {
        for await isOnline in monitor.updates() {
            self.isOnline = isOnline
        }
